/**
 * One document row.
 */
public struct DocItem: Equatable, Hashable {
    /**
     * Stable id (the core's `DocumentId`), as a string.
     */
    public let id: String
    /**
     * `w2-acme-2025`; the shell adds the `🐙/` prefix via `handle_string`.
     */
    public let codename: String
    /**
     * File name at drop time, shown while processing.
     */
    public let originalName: String
    /**
     * Where the original lives now, for "Open file" (reveal in Finder).
     */
    public let path: String
    /**
     * Human kind label: "W-2", "1099-INT", "scan", "closing statement".
     */
    public let kindLabel: String
    public let state: DocState
    /**
     * Values inked so far, for "6 inked".
     */
    public let inked: UInt32
    /**
     * "reading", "reading the scan", "queued", "page 3 of 11".
     */
    public let statusNote: String?
    public let loader: Loader
    /**
     * Set while `state == NeedsAttention`.
     */
    public let question: ReviewQuestion?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Stable id (the core's `DocumentId`), as a string.
         */id: String, 
        /**
         * `w2-acme-2025`; the shell adds the `🐙/` prefix via `handle_string`.
         */codename: String, 
        /**
         * File name at drop time, shown while processing.
         */originalName: String, 
        /**
         * Where the original lives now, for "Open file" (reveal in Finder).
         */path: String, 
        /**
         * Human kind label: "W-2", "1099-INT", "scan", "closing statement".
         */kindLabel: String, state: DocState, 
        /**
         * Values inked so far, for "6 inked".
         */inked: UInt32, 
        /**
         * "reading", "reading the scan", "queued", "page 3 of 11".
         */statusNote: String?, loader: Loader, 
        /**
         * Set while `state == NeedsAttention`.
         */question: ReviewQuestion?) {
        self.id = id
        self.codename = codename
        self.originalName = originalName
        self.path = path
        self.kindLabel = kindLabel
        self.state = state
        self.inked = inked
        self.statusNote = statusNote
        self.loader = loader
        self.question = question
    }

    

    
}

