/**
 * Implemented in Swift. Fired on any queue change, from a background thread;
 * the Swift side hops to the main actor before touching UI.
 *
 * Note: UniFFI 0.32 soft-deprecates `callback_interface` in favour of
 * `#[uniffi::export(foreign)]` with `Arc<dyn Trait>`. It still works and is
 * what the generated Swift protocol expects today.
 */
public protocol QueueListener: AnyObject, Sendable {
    
    func queueChanged() 
    
}


// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceQueueListener {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceQueueListener = UniffiVTableCallbackInterfaceQueueListener(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterCallbackInterfaceQueueListener.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface QueueListener: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterCallbackInterfaceQueueListener.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface QueueListener: handle missing in uniffiClone")
            }
        },
        queueChanged: { (
            uniffiHandle: UInt64,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceQueueListener.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.queueChanged(
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceQueueListener> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceQueueListener>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitQueueListener() {
    uniffi_inker_ffi_fn_init_callback_vtable_queuelistener(UniffiCallbackInterfaceQueueListener.vtablePtr)
}

